}

// 🟢 安全: 清除所有权限缓存
public void downgradeUser(Long userId) {
    User user = userRepository.findById(userId).get();
    user.setRole("BASIC");
    userRepository.save(user);

    // 清除权限缓存
    permissionCache.evict(userId);
    // 使现有会话失效
    sessionRegistry.getAllSessions(user, false)
        .forEach(s -> s.expireNow());
}
