        else if (DATA_SCOPE_DEPT.equals(dataScope)) {
            allowedDeptIds.add(user.getDeptId());
        }
    }

    BaseEntity baseEntity = (BaseEntity) joinPoint.getArgs()[0];
    baseEntity.getParams().put("dataScopeIds", allowedDeptIds);
}
