    where d.del_flag = '0'
    <if test="deptName != null and deptName != ''">
        AND dept_name like concat('%', #{deptName}, '%')
    </if>

    <!-- ✓ 使用foreach处理数据权限过滤 -->
    <if test="dataScopeIds != null and dataScopeIds.size() > 0">
        AND d.dept_id IN
        <foreach collection="dataScopeIds" item="id" open="(" close=")" separator=",">
