// 安全的文件上传处理
@PostMapping("/upload")
@RequiresPermissions("file:upload")
public AjaxResult uploadFile(@Validated MultipartFile file) {
    // 1. 文件类型验证
    if (!isAllowedFileType(file)) {
        return error("文件类型不允许");
    }

    // 2. 文件大小限制
