## Vue 安全

### 1. XSS 漏洞

```vue
<!-- 🔴 v-html 指令 -->
<template>
    <div v-html="userContent"></div>
</template>

<!-- 攻击: userContent = '<img src=x onerror=alert(1)>' -->

<!-- 🟢 安全: 使用 DOMPurify -->
<template>
    <div v-html="sanitizedContent"></div>
</template>

<script>
import DOMPurify from 'dompurify';

export default {
    computed: {
        sanitizedContent() {
            return DOMPurify.sanitize(this.userContent);
        }
    }
}
</script>
```

```vue
<!-- 🔴 动态组件名 -->
<component :is="userInput" />
<!-- 攻击: userInput = 'script' 可能导致问题 -->

<!-- 🟢 安全: 白名单验证 -->
<script>
const allowedComponents = ['UserCard', 'ProductCard', 'CommentCard'];

export default {
    computed: {
        safeComponent() {
            return allowedComponents.includes(this.userInput)
                ? this.userInput
                : 'DefaultCard';
        }
    }
}
</script>
```

```vue
<!-- 🔴 :href 绑定 -->
<a :href="userUrl">Link</a>
<!-- 攻击: userUrl = 'javascript:alert(1)' -->

<!-- 🟢 安全: 验证 URL -->
<template>
    <a :href="safeUrl">Link</a>
</template>

<script>
export default {
    computed: {
        safeUrl() {
            try {
                const url = new URL(this.userUrl);
                if (['http:', 'https:'].includes(url.protocol)) {
                    return this.userUrl;
                }
            } catch {}
            return '#';
        }
    }
}
</script>
```

