## 通用安全问题

### 1. 本地存储安全

```javascript
// 🔴 在 localStorage 存储敏感数据
localStorage.setItem('authToken', token);
localStorage.setItem('user', JSON.stringify({ password: 'secret' }));

// 风险:
// - XSS 可以读取 localStorage
// - 没有过期机制
// - 跨标签页共享

// 🟢 安全替代方案
// 1. 使用 httpOnly cookie (后端设置)
// 2. 使用 sessionStorage (会话级别)
// 3. 内存中存储 (刷新丢失，但更安全)

// 如果必须使用 localStorage，加密存储
import CryptoJS from 'crypto-js';

const encryptedToken = CryptoJS.AES.encrypt(token, SECRET_KEY).toString();
localStorage.setItem('authToken', encryptedToken);
```

### 2. CSP (内容安全策略)

```html
<!-- 🟢 推荐的 CSP 配置 -->
<meta http-equiv="Content-Security-Policy" content="
    default-src 'self';
    script-src 'self' 'nonce-RANDOM_NONCE';
    style-src 'self' 'unsafe-inline';
    img-src 'self' data: https:;
    font-src 'self';
    connect-src 'self' https://api.example.com;
    frame-ancestors 'none';
    base-uri 'self';
    form-action 'self';
">

<!-- React/Vue/Angular 需要的调整 -->
<!-- 开发环境可能需要 'unsafe-eval' 但生产环境应移除 -->
```

```javascript
// Next.js CSP 配置 (next.config.js)
const securityHeaders = [
    {
        key: 'Content-Security-Policy',
        value: `
            default-src 'self';
            script-src 'self' 'unsafe-inline' 'unsafe-eval';
            style-src 'self' 'unsafe-inline';
        `.replace(/\s{2,}/g, ' ').trim()
    }
];

module.exports = {
    async headers() {
        return [{
            source: '/:path*',
            headers: securityHeaders
        }];
    }
};
```

### 3. 第三方脚本安全

```html
<!-- 🔴 直接加载第三方脚本 -->
<script src="https://cdn.example.com/library.js"></script>

<!-- 🟢 安全: 使用 SRI (Subresource Integrity) -->
<script
    src="https://cdn.example.com/library.js"
    integrity="sha384-HASH_VALUE"
    crossorigin="anonymous"
></script>
```

```javascript
// 检查依赖安全
// package.json 审计
npm audit
yarn audit

// 检查已知漏洞
npx snyk test
```

### 4. postMessage 安全

```javascript
// 🔴 不验证来源的 postMessage
window.addEventListener('message', (event) => {
    // 🔴 没有验证 origin
    const data = event.data;
    document.getElementById('content').innerHTML = data;  // XSS!
});

// 🟢 安全: 验证 origin
window.addEventListener('message', (event) => {
    // 验证来源
    if (event.origin !== 'https://trusted-site.com') {
        return;
    }

    // 验证数据类型
    if (typeof event.data !== 'object' || !event.data.type) {
        return;
    }

    // 安全处理
    if (event.data.type === 'updateContent') {
        document.getElementById('content').textContent = event.data.value;
    }
});
```

### 5. WebSocket 安全

```javascript
// 🔴 不验证的 WebSocket 消息
socket.onmessage = (event) => {
    const data = JSON.parse(event.data);
    element.innerHTML = data.content;  // XSS!
};

// 🟢 安全
socket.onmessage = (event) => {
    try {
        const data = JSON.parse(event.data);

        // 验证消息类型
        if (!['chat', 'notification'].includes(data.type)) {
            return;
        }

        // 安全渲染
        element.textContent = data.content;
    } catch (e) {
        console.error('Invalid message');
    }
};
```

