## 日志框架安全配置

### Log4j2 安全配置

```xml
<!-- log4j2.xml -->
<Configuration status="WARN">
    <!-- 禁用 JNDI Lookup -->
    <Properties>
        <Property name="log4j2.formatMsgNoLookups">true</Property>
    </Properties>

    <Appenders>
        <RollingFile name="File" fileName="app.log"
                     filePattern="app-%d{yyyy-MM-dd}-%i.log.gz">
            <!-- 使用安全的 Pattern -->
            <PatternLayout>
                <!-- %encode{} 对特殊字符编码 -->
                <Pattern>%d{ISO8601} [%t] %-5level %logger{36} - %encode{%msg}{CRLF}%n</Pattern>
            </PatternLayout>
            <Policies>
                <SizeBasedTriggeringPolicy size="10MB"/>
                <TimeBasedTriggeringPolicy/>
            </Policies>
            <!-- 限制文件数量防止磁盘耗尽 -->
            <DefaultRolloverStrategy max="30"/>
        </RollingFile>
    </Appenders>

    <Loggers>
        <!-- 生产环境禁用 DEBUG -->
        <Root level="INFO">
            <AppenderRef ref="File"/>
        </Root>
    </Loggers>
</Configuration>
```

### Logback 安全配置

```xml
<!-- logback.xml -->
<configuration>
    <!-- 自定义转换器过滤 CRLF -->
    <conversionRule conversionWord="safeMsg"
                    converterClass="com.example.SafeMessageConverter"/>

    <appender name="FILE" class="ch.qos.logback.core.rolling.RollingFileAppender">
        <file>app.log</file>
        <rollingPolicy class="ch.qos.logback.core.rolling.TimeBasedRollingPolicy">
            <fileNamePattern>app.%d{yyyy-MM-dd}.log</fileNamePattern>
            <maxHistory>30</maxHistory>
            <totalSizeCap>1GB</totalSizeCap>
        </rollingPolicy>
        <encoder>
            <pattern>%d{ISO8601} [%thread] %-5level %logger{36} - %safeMsg%n</pattern>
        </encoder>
    </appender>

    <root level="INFO">
        <appender-ref ref="FILE"/>
    </root>
</configuration>
```

